const FIXTURE_JSON: &str = include_str!("data/GlobeSurfaceTile.json");

#[derive(Debug)]
struct MockSurfaceTerrainData {
    height_to_return: f64,
    upsampled: bool,
    child_available: bool,
}

impl SurfaceTerrainData for MockSurfaceTerrainData {
    fn interpolate_height(
        &self,
        _rectangle: &Rectangle,
        _longitude: f64,
        _latitude: f64,
    ) -> Option<f64> {
        Some(self.height_to_return)
    }

    fn is_child_available(&self, _this_x: u32, _this_y: u32, _child_x: u32, _child_y: u32) -> bool {
        self.child_available
    }

    fn was_created_by_upsampling(&self) -> bool {
        self.upsampled
    }
}

fn create_test_mesh(min_height: f64, max_height: f64) -> TerrainMesh {
    let encoding = TerrainEncoding::new(TerrainEncodingOptions::default()).expect("valid encoding");
    TerrainMesh::new(TerrainMeshOptions {
        center: Cartesian3::ZERO,
        vertices: vec![0.0; 24],
        indices: TypedArray::Uint16(vec![0, 1, 2]),
        index_count_without_skirts: Some(3),
        vertex_count_without_skirts: 3,
        minimum_height: min_height,
        maximum_height: max_height,
        rectangle: Rectangle::new(-1.0, -1.0, 1.0, 1.0),
        bounding_sphere_3d: BoundingSphere::new(Cartesian3::ZERO, 100.0),
        occludee_point_in_scaled_space: None,
        vertex_stride: Some(6),
        oriented_bounding_box: None,
        encoding,
        edges: TerrainEdgeIndices::default(),
    })
}

#[test]
fn test_default_construction_against_cesiumjs_fixture() {
    let fixture: Value = serde_json::from_str(FIXTURE_JSON).expect("valid fixture JSON");
    let real_js = &fixture["real_cesiumjs_output"]["default_construction"];

    let tile = GlobeSurfaceTile::new();

    assert_eq!(
        tile.eligible_for_unloading(),
        real_js["eligible_for_unloading"].as_bool().unwrap(),
        "eligible_for_unloading parity"
    );
    assert_eq!(
        tile.has_rendered_mesh(),
        real_js["rendered_mesh_defined"].as_bool().unwrap(),
        "renderedMesh defined parity"
    );
    assert_eq!(
        tile.is_clipped,
        real_js["is_clipped"].as_bool().unwrap(),
        "isClipped parity"
    );
    assert_eq!(
        tile.clipped_by_boundaries,
        real_js["clipped_by_boundaries"].as_bool().unwrap(),
        "clippedByBoundaries parity"
    );
    assert_eq!(
        tile.terrain_state.value(),
        real_js["terrain_state"].as_i64().unwrap() as i32,
        "terrainState value parity"
    );

    let js_wm = real_js["water_mask_translation_and_scale"].as_array().unwrap();
    assert_eq!(tile.water_mask_translation_and_scale.x, js_wm[0].as_f64().unwrap());
    assert_eq!(tile.water_mask_translation_and_scale.y, js_wm[1].as_f64().unwrap());
    assert_eq!(tile.water_mask_translation_and_scale.z, js_wm[2].as_f64().unwrap());
    assert_eq!(tile.water_mask_translation_and_scale.w, js_wm[3].as_f64().unwrap());

    assert_eq!(tile.imagery.len(), real_js["imagery_length"].as_u64().unwrap() as usize);
    assert_eq!(tile.has_vertex_array, real_js["vertex_array_defined"].as_bool().unwrap());
    assert_eq!(tile.occludee_point_in_scaled_space, Cartesian3::ZERO);
    assert!(tile.bounding_volume_source_tile.is_none());
    assert!(!tile.bounding_volume_is_from_mesh);
    assert_eq!(tile.pick_bounding_sphere, BoundingSphere::default());
}

#[test]
fn test_unloading_eligibility_parity_against_cesiumjs_fixture() {
    let fixture: Value = serde_json::from_str(FIXTURE_JSON).expect("valid fixture JSON");
    let cases = fixture["real_cesiumjs_output"]["unloading_eligibility"]["terrain_state_cases"]
        .as_array()
        .unwrap();

    let mut tile = GlobeSurfaceTile::new();

    for case in cases {
        let state_name = case["terrain_state"].as_str().unwrap();
        let expected_eligible = case["eligible_for_unloading"].as_bool().unwrap();

        match state_name {
            "FAILED" => tile.terrain_state = TerrainState::Failed,
            "UNLOADED" => tile.terrain_state = TerrainState::Unloaded,
            "RECEIVING" => tile.terrain_state = TerrainState::Receiving,
            "RECEIVED" => tile.terrain_state = TerrainState::Received,
            "TRANSFORMING" => tile.terrain_state = TerrainState::Transforming,
            "TRANSFORMED" => tile.terrain_state = TerrainState::Transformed,
            "READY" => tile.terrain_state = TerrainState::Ready,
            other => panic!("unknown terrain state: {other}"),
        }

        assert_eq!(
            tile.eligible_for_unloading(),
            expected_eligible,
            "Terrain state {state_name} unloading eligibility mismatch"
        );
    }

    // Imagery loading state cases
    let imagery_cases = fixture["real_cesiumjs_output"]["unloading_eligibility"]["imagery_state_cases"]
        .as_array()
        .unwrap();

    for case in imagery_cases {
        let state_name = case["imagery_state"].as_str().unwrap();
        let expected_eligible = case["eligible_for_unloading"].as_bool().unwrap();

        let mut tile = GlobeSurfaceTile::new();
        tile.terrain_state = TerrainState::Ready;

        let img_state = match state_name {
            "UNLOADED" => ImageryState::Unloaded,
            "TRANSITIONING" => ImageryState::Transitioning,
            "RECEIVED" => ImageryState::Received,
            "TEXTURE_LOADED" => ImageryState::TextureLoaded,
            "READY" => ImageryState::Ready,
            "FAILED" => ImageryState::Failed,
            "INVALID" => ImageryState::Invalid,
            "PLACEHOLDER" => ImageryState::Placeholder,
            other => panic!("unknown imagery state: {other}"),
        };

        let mut img = Imagery::new(0, 0, 0, Rectangle::new(-1.0, -1.0, 1.0, 1.0), None);
        img.state = img_state;
        let img_cell = Rc::new(RefCell::new(img));
        let tile_imagery = TileImagery::new(img_cell, Cartesian4::ZERO, false);
        tile.imagery.push(tile_imagery);

        assert_eq!(
            tile.eligible_for_unloading(),
            expected_eligible,
            "Imagery state {state_name} unloading eligibility mismatch"
        );
    }

    // Receiving terrain with ready imagery
    let mut tile_both = GlobeSurfaceTile::new();
    tile_both.terrain_state = TerrainState::Receiving;
    let mut ready_img = Imagery::new(0, 0, 0, Rectangle::new(-1.0, -1.0, 1.0, 1.0), None);
    ready_img.state = ImageryState::Ready;
    tile_both.imagery.push(TileImagery::new(Rc::new(RefCell::new(ready_img)), Cartesian4::ZERO, false));
    let receiving_with_ready_expected = fixture["real_cesiumjs_output"]["unloading_eligibility"]
        ["receiving_terrain_with_ready_imagery"]
        .as_bool()
        .unwrap();
    assert_eq!(
        tile_both.eligible_for_unloading(),
        receiving_with_ready_expected,
        "Receiving terrain with ready imagery mismatch"
    );
}

#[test]
fn test_water_mask_translation_and_scale_against_fixture_and_analytical() {
    let fixture: Value = serde_json::from_str(FIXTURE_JSON).expect("valid fixture JSON");
    let test_cases = fixture["real_cesiumjs_output"]["water_mask_translation_and_scale"]
        .as_array()
        .unwrap();

    for case in test_cases {
        let name = case["name"].as_str().unwrap();
        let tile_info = &case["tile"];
        let source_info = &case["source"];
        let expected_res = case["translation_and_scale"].as_array().unwrap();

        let tile_rect = Rectangle::new(
            tile_info["west"].as_f64().unwrap(),
            tile_info["south"].as_f64().unwrap(),
            tile_info["east"].as_f64().unwrap(),
            tile_info["north"].as_f64().unwrap(),
        );

        let source_rect = Rectangle::new(
            source_info["west"].as_f64().unwrap(),
            source_info["south"].as_f64().unwrap(),
            source_info["east"].as_f64().unwrap(),
            source_info["north"].as_f64().unwrap(),
        );

        let result = GlobeSurfaceTile::compute_water_mask_translation_and_scale(&tile_rect, &source_rect);

        assert!(
            (result.x - expected_res[0].as_f64().unwrap()).abs() < 1e-12,
            "Case {name} translation.x parity"
        );
        assert!(
            (result.y - expected_res[1].as_f64().unwrap()).abs() < 1e-12,
            "Case {name} translation.y parity"
        );
        assert!(
            (result.z - expected_res[2].as_f64().unwrap()).abs() < 1e-12,
            "Case {name} scale.x parity"
        );
        assert!(
            (result.w - expected_res[3].as_f64().unwrap()).abs() < 1e-12,
            "Case {name} scale.y parity"
        );
    }
}

#[test]
fn test_ancestor_terrain_traversal_parity() {
    let scheme: Arc<dyn TilingScheme> = Arc::new(GeographicTilingScheme::default());

    // Root tile with non-upsampled data
    let root = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: Arc::clone(&scheme),
        x: 0,
        y: 0,
        level: 0,
        parent: None,
    });
    let root_handle = Rc::new(RefCell::new(root));
    let mut root_gst = GlobeSurfaceTile::new();
    root_gst.terrain_data = Some(Box::new(MockSurfaceTerrainData {
        height_to_return: 100.0,
        upsampled: false,
        child_available: true,
    }));
    root_handle.borrow_mut().data = Some(Box::new(root_gst));

    // Mid tile with upsampled data
    let mid = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: Arc::clone(&scheme),
        x: 0,
        y: 0,
        level: 1,
        parent: Some(Rc::downgrade(&root_handle)),
    });
    let mid_handle = Rc::new(RefCell::new(mid));
    let mut mid_gst = GlobeSurfaceTile::new();
    mid_gst.terrain_data = Some(Box::new(MockSurfaceTerrainData {
        height_to_return: 100.0,
        upsampled: true,
        child_available: true,
    }));
    mid_handle.borrow_mut().data = Some(Box::new(mid_gst));

    // Leaf tile with no terrain data
    let leaf = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: Arc::clone(&scheme),
        x: 0,
        y: 0,
        level: 2,
        parent: Some(Rc::downgrade(&mid_handle)),
    });

    let ancestor = GlobeSurfaceTile::find_ancestor_tile_with_terrain_data(&leaf);
    assert!(ancestor.is_some(), "Should locate ancestor with non-upsampled terrain data");
    assert_eq!(ancestor.unwrap().borrow().level, 0, "Ancestor must be root (skipping upsampled mid)");
}

#[test]
fn test_initialize_quadtree_tile_state() {
    let fixture: Value = serde_json::from_str(FIXTURE_JSON).expect("valid fixture JSON");
    let unavail_js = &fixture["real_cesiumjs_output"]["initialization"]["unavailable_tile"];
    let avail_js = &fixture["real_cesiumjs_output"]["initialization"]["available_tile"];

    let scheme: Arc<dyn TilingScheme> = Arc::new(GeographicTilingScheme::default());

    // Case 1: unavailable tile
    let mut tile_unavail = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: Arc::clone(&scheme),
        x: 0,
        y: 0,
        level: 1,
        parent: None,
    });
    GlobeSurfaceTile::initialize(&mut tile_unavail, Some(false));

    assert_eq!(
        tile_unavail.state,
        QuadtreeTileLoadState::Loading,
        "Quadtree tile state becomes Loading"
    );
    let gst = tile_unavail.data.as_ref().unwrap().as_any().downcast_ref::<GlobeSurfaceTile>().unwrap();
    assert_eq!(
        gst.terrain_state.value(),
        unavail_js["terrain_state"].as_i64().unwrap() as i32,
        "Unavailable terrain state is Failed (0)"
    );

    // Case 2: available tile
    let mut tile_avail = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: Arc::clone(&scheme),
        x: 1,
        y: 1,
        level: 1,
        parent: None,
    });
    GlobeSurfaceTile::initialize(&mut tile_avail, Some(true));
    assert_eq!(tile_avail.state, QuadtreeTileLoadState::Loading);
    let gst_avail = tile_avail.data.as_ref().unwrap().as_any().downcast_ref::<GlobeSurfaceTile>().unwrap();
    assert_eq!(
        gst_avail.terrain_state.value(),
        avail_js["terrain_state"].as_i64().unwrap() as i32,
        "Available terrain state is Unloaded (1)"
    );
}

#[test]
fn test_free_resources_parity() {
    let fixture: Value = serde_json::from_str(FIXTURE_JSON).expect("valid fixture JSON");
    let free_js = &fixture["real_cesiumjs_output"]["free_resources"];

    let mut tile = GlobeSurfaceTile::new();
    tile.set_mesh(create_test_mesh(10.0, 50.0));
    tile.set_vertex_array_present(true);
    tile.has_water_mask_texture = true;
    tile.water_mask_translation_and_scale = Cartesian4::new(0.5, 0.5, 0.25, 0.25);

    let mut img = Imagery::new(0, 0, 0, Rectangle::new(-1.0, -1.0, 1.0, 1.0), None);
    img.state = ImageryState::Ready;
    tile.imagery.push(TileImagery::new(Rc::new(RefCell::new(img)), Cartesian4::ZERO, false));

    assert_eq!(tile.terrain_state, TerrainState::Ready);
    assert!(tile.has_rendered_mesh());
    assert_eq!(tile.imagery.len(), 1);

    tile.free_resources();

    assert_eq!(
        tile.terrain_state.value(),
        free_js["terrain_state_after_free"].as_i64().unwrap() as i32,
        "terrainState after free parity"
    );
    assert_eq!(
        tile.has_rendered_mesh(),
        free_js["mesh_defined_after_free"].as_bool().unwrap(),
        "mesh defined after free parity"
    );
    assert_eq!(
        tile.has_water_mask_texture,
        free_js["water_mask_defined_after_free"].as_bool().unwrap(),
        "waterMask defined after free parity"
    );
    assert_eq!(
        tile.imagery.len(),
        free_js["imagery_length_after_free"].as_u64().unwrap() as usize,
        "imagery length after free parity"
    );
    assert_eq!(
        tile.water_mask_translation_and_scale,
        Cartesian4::new(0.0, 0.0, 1.0, 1.0),
        "translation and scale reset"
    );
}

#[test]
fn test_quadtree_tile_data_trait_implementation() {
    let mut tile = GlobeSurfaceTile::new();
    tile.set_mesh(create_test_mesh(15.0, 85.0));
    tile.set_vertex_array_present(true);

    let tbr = TileBoundingRegion::new(TileBoundingRegionOptions {
        rectangle: Rectangle::new(0.0, 0.0, 1.0, 1.0),
        minimum_height: Some(15.0),
        maximum_height: Some(85.0),
        ellipsoid: None,
        compute_bounding_volumes: Some(false),
    });
    tile.tile_bounding_region = Some(tbr);

    let mut tile_data: Box<dyn QuadtreeTileData> = Box::new(tile);

    assert!(tile_data.eligible_for_unloading());
    assert!(tile_data.has_mesh());
    assert_eq!(tile_data.minimum_height(), Some(15.0));
    assert!(!tile_data.was_created_by_upsampling());

    let downcasted = tile_data.as_any().downcast_ref::<GlobeSurfaceTile>();
    assert!(downcasted.is_some(), "downcast_ref to GlobeSurfaceTile succeeds");

    let downcasted_mut = tile_data.as_any_mut().downcast_mut::<GlobeSurfaceTile>();
    assert!(downcasted_mut.is_some(), "downcast_mut to GlobeSurfaceTile succeeds");

    // Pick test via trait
    let ray = Ray::new(Cartesian3::new(0.0, 0.0, 500.0), Cartesian3::new(0.0, 0.0, -1.0));
    let _ = tile_data.pick(&ray, SceneMode::Scene3D, true);

    // Free resources via trait
    tile_data.free_resources();
    assert!(!tile_data.has_mesh());
}

#[test]
fn test_height_sampling_via_terrain_data_and_concrete_heightmap() {
    let mut tile = GlobeSurfaceTile::new();
    let mock = MockSurfaceTerrainData {
        height_to_return: 42.5,
        upsampled: false,
        child_available: true,
    };
    assert!(mock.is_child_available(0, 0, 0, 0));
    assert!(mock.can_upsample());

    tile.terrain_data = Some(Box::new(mock));
    tile.tile_bounding_region = Some(TileBoundingRegion::new(TileBoundingRegionOptions {
        rectangle: Rectangle::new(0.0, 0.0, 1.0, 1.0),
        minimum_height: Some(0.0),
        maximum_height: Some(100.0),
        ellipsoid: None,
        compute_bounding_volumes: Some(false),
    }));

    let pos = Cartographic::new(0.5, 0.5, 0.0);
    let sample = tile.sample_height(&pos);
    assert_eq!(sample, Some(42.5), "Height sampling returns interpolated height");

    // Integration test with concrete core HeightmapTerrainData
    let buffer = TypedArray::Uint8(vec![10, 20, 30, 40]);
    let htd_options = HeightmapTerrainDataOptions {
        buffer,
        width: 2,
        height: 2,
        child_tile_mask: 15,
        water_mask: None,
        structure: HeightmapTerrainStructure::default(),
        encoding: HeightmapEncoding::None,
        created_by_upsampling: false,
    };
    let htd = HeightmapTerrainData::new(htd_options).expect("valid heightmap terrain data");
    let mut concrete_tile = GlobeSurfaceTile::new();
    concrete_tile.rectangle = Some(Rectangle::new(0.0, 0.0, 1.0, 1.0));
    concrete_tile.terrain_data = Some(Box::new(htd));
    let concrete_sample = concrete_tile.sample_height(&pos);
    assert!(concrete_sample.is_some(), "Interpolated height from concrete HeightmapTerrainData");
}

#[test]
fn test_exaggeration_update_and_custom_data_invalidation() {
    let scheme: Arc<dyn TilingScheme> = Arc::new(GeographicTilingScheme::default());
    let mut quad_tile = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: scheme,
        x: 0,
        y: 0,
        level: 0,
        parent: None,
    });

    quad_tile.custom_data.push(QuadtreeCustomData {
        id: 1,
        position_cartographic: Cartographic::new(0.1, 0.1, 0.0),
        position_on_ellipsoid_surface: None,
        level: 4,
        callback: None,
    });

    let mut gst = GlobeSurfaceTile::new();
    gst.set_mesh(create_test_mesh(0.0, 100.0));
    gst.set_vertex_array_present(true);

    // Exaggerate terrain by factor of 2.5
    gst.update_exaggeration(&mut quad_tile, 2.5, 0.0);

    assert_eq!(
        quad_tile.custom_data[0].level, -1,
        "Custom data level must be invalidated to -1 so height update triggers"
    );
    assert_eq!(
        gst.mesh.borrow().as_ref().unwrap().encoding.exaggeration,
        2.5,
        "Encoding exaggeration updated"
    );

    // Call update_scene_mode to verify cache invalidation
    gst.update_scene_mode(Some(TerrainSceneMode::Scene3D));
}

#[test]
fn test_process_imagery_lifecycle() {
    let scheme: Arc<dyn TilingScheme> = Arc::new(GeographicTilingScheme::default());
    let mut quad_tile = QuadtreeTile::new(QuadtreeTileOptions {
        tiling_scheme: scheme,
        x: 0,
        y: 0,
        level: 0,
        parent: None,
    });
    quad_tile.upsampled_from_parent = true;
    quad_tile.renderable = true;

    let mut gst = GlobeSurfaceTile::new();

    // With empty imagery: done loading is true, renderable stays true, upsampled remains true
    let is_done = gst.process_imagery(&mut quad_tile, None, false);
    assert!(is_done);
    assert!(quad_tile.renderable);
    assert!(quad_tile.upsampled_from_parent);

    // Add a ready imagery skeleton
    let mut ready_img = Imagery::new(0, 0, 0, Rectangle::new(-1.0, -1.0, 1.0, 1.0), None);
    ready_img.state = ImageryState::Ready;
    let mut tile_img = TileImagery::new(Rc::new(RefCell::new(ready_img)), Cartesian4::ZERO, false);
    tile_img.ready_imagery = Some(Rc::clone(tile_img.loading_imagery.as_ref().unwrap()));
    tile_img.loading_imagery = None;
    gst.imagery.push(tile_img);

    let is_done2 = gst.process_imagery(&mut quad_tile, None, false);
    assert!(is_done2);
    assert!(quad_tile.renderable);
    assert!(!quad_tile.upsampled_from_parent);
}

#[test]
fn test_pick_on_globe_surface_tile() {
    let mut gst = GlobeSurfaceTile::new();
    let projection = GeographicProjection::new(cesium_rs::core::Ellipsoid::WGS84);
    let ray = Ray::new(Cartesian3::new(0.0, 0.0, 100.0), Cartesian3::new(0.0, 0.0, -1.0));

    // Without mesh or vertexArray: returns None
    assert_eq!(gst.pick(&ray, Some(TerrainSceneMode::Scene3D), &projection, true), None);

    // With CPU-only mesh (no vertex array): still returns None (CPU mesh alone is not rendered)
    gst.set_mesh(create_test_mesh(0.0, 10.0));
    assert_eq!(gst.pick(&ray, Some(TerrainSceneMode::Scene3D), &projection, true), None);

    // With GPU vertex array present: can pick
    gst.set_vertex_array_present(true);
    let _ = gst.pick(&ray, Some(TerrainSceneMode::Scene3D), &projection, true);
}
